static byte[] bytes(JsonNode command,int index){
    JsonNode value=command.get(index);
    if(value==null)throw new IllegalArgumentException("Missing Redis argument");
    if(value.isTextual())return value.asText().getBytes(StandardCharsets.UTF_8);
    if(!value.isObject()||value.size()!=1||!value.path("base64").isTextual())
        throw new IllegalArgumentException("Redis values must be text or an object containing only base64");
    String encoded=value.path("base64").asText();
    if(encoded.length()>87384)throw new IllegalArgumentException("Binary values exceed the 64 KiB per-value input allowance");
    try{
        byte[] decoded=Base64.getDecoder().decode(encoded);
        if(decoded.length>65536||!Base64.getEncoder().encodeToString(decoded).equals(encoded))
            throw new IllegalArgumentException();
        return decoded;
    }catch(IllegalArgumentException invalid){
        throw new IllegalArgumentException("Binary arguments require canonical padded base64, at most 64 KiB decoded");
    }
}

package io.doindev.codegraph.dba;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Structural native-command review. Classifications are not authorization tokens. */
final class NativeCommand {
    enum Effect { READ, WRITE, DESTRUCTIVE, ADMINISTRATION }
    record Classification(String category, Effect effect, boolean reusableRead, String reason) {
        ObjectNode json() {
            return Profiles.JSON.createObjectNode().put("category", category)
                    .put("effect", effect.name().toLowerCase(Locale.ROOT))
                    .put("readOnly", effect == Effect.READ).put("reusableRead", reusableRead)
                    .put("reason", reason);
        }
    }

    private static final Set<String> SAFE_MONGO_EXPRESSIONS = Set.of(
            "$and", "$or", "$nor", "$not", "$eq", "$ne", "$gt", "$gte", "$lt", "$lte",
            "$in", "$nin", "$exists", "$type", "$regex", "$options", "$all", "$elemMatch", "$size",
            "$expr", "$literal", "$add", "$subtract", "$multiply", "$divide", "$mod", "$abs",
            "$ceil", "$floor", "$round", "$sum", "$avg", "$min", "$max", "$first", "$last",
            "$push", "$addToSet", "$count", "$cond", "$ifNull", "$switch", "$let", "$map", "$filter",
            "$reduce", "$concat", "$concatArrays", "$arrayElemAt", "$isArray", "$objectToArray",
            "$arrayToObject", "$toString", "$toInt", "$toLong", "$toDouble", "$toDecimal", "$toDate",
            "$convert", "$dateToString", "$dateFromString", "$year", "$month", "$dayOfMonth",
            "$sortArray", "$slice", "$setUnion", "$setIntersection", "$setDifference", "$mergeObjects",
            "$oid", "$date", "$numberLong", "$numberInt", "$numberDecimal", "$numberDouble",
            "$binary", "$timestamp", "$regularExpression", "$minKey", "$maxKey", "$uuid");
    private static final Set<String> READ_STAGES = Set.of("$match", "$project", "$sort", "$limit", "$skip",
            "$group", "$unwind", "$addFields", "$set", "$unset", "$replaceRoot", "$replaceWith",
            "$count", "$sortByCount", "$sample", "$bucket", "$bucketAuto");
    private static final Set<String> MONGO_META = Set.of("listCollections", "listIndexes", "collStats", "dbStats");
    private static final Set<String> REDIS_READ = Set.of("GET", "GETRANGE", "STRLEN", "MGET", "TYPE", "EXISTS",
            "TTL", "PTTL", "EXPIRETIME", "PEXPIRETIME", "HGET", "HMGET", "HGETALL", "HLEN", "HEXISTS",
            "HKEYS", "HVALS", "HSCAN", "LRANGE", "LINDEX", "LLEN", "SMEMBERS", "SSCAN", "SCARD",
            "SISMEMBER", "SMISMEMBER", "ZRANGE", "ZREVRANGE", "ZRANGEBYSCORE", "ZCARD", "ZSCORE",
            "ZMSCORE", "ZRANK", "ZREVRANK", "ZCOUNT", "ZSCAN", "XRANGE", "XREVRANGE", "XLEN",
            "GETBIT", "BITCOUNT", "BITPOS", "GEOPOS", "GEODIST", "GEOSEARCH", "SCAN", "DBSIZE", "PING");
    private static final Set<String> REDIS_WRITE = Set.of("SET", "MSET", "SETNX", "MSETNX", "APPEND",
            "INCR", "INCRBY", "INCRBYFLOAT", "DECR", "DECRBY", "SETRANGE", "HSET", "HSETNX", "HMSET",
            "HINCRBY", "HINCRBYFLOAT", "LPUSH", "RPUSH", "LPUSHX", "RPUSHX", "LSET", "LINSERT",
            "SADD", "ZADD", "ZINCRBY", "XADD", "SETBIT", "BITFIELD", "PFADD", "PFMERGE", "GEOADD",
            "PUBLISH", "SPUBLISH", "XACK", "EXPIRE", "PEXPIRE", "EXPIREAT", "PEXPIREAT", "PERSIST");
    private static final Set<String> REDIS_DESTRUCTIVE = Set.of("DEL", "UNLINK", "GETDEL", "RENAME", "RENAMENX",
            "HDEL", "LPOP", "RPOP", "BLPOP", "BRPOP", "LMOVE", "BLMOVE", "LTRIM", "LREM", "SREM",
            "SPOP", "SMOVE", "ZREM", "ZPOPMIN", "ZPOPMAX", "BZPOPMIN", "BZPOPMAX", "XDEL", "XTRIM",
            "FLUSHDB", "FLUSHALL", "RESTORE", "MIGRATE");

    static Classification classify(NativeTarget target, JsonNode command) {
        bound(command);
        return switch (target.transport()) {
            case MONGODB -> mongo(target, command);
            case REDIS -> redis(command);
            default -> throw new IllegalArgumentException("Use SQL tools for JDBC connections");
        };
    }

    private static Classification mongo(NativeTarget target, JsonNode command) {
        if (!command.isObject() || command.isEmpty()) throw new IllegalArgumentException("MongoDB command must be a nonempty Extended JSON object");
        String name = command.fieldNames().next();
        if (command.has("$db") || command.has("lsid") || command.has("txnNumber") || command.has("autocommit")
                || command.has("startTransaction") || command.has("$clusterTime") || command.has("apiStrict")) {
            throw new IllegalArgumentException("Database and session context are managed by the application");
        }
        if (Set.of("find", "aggregate", "insert", "update", "delete", "findAndModify", "listIndexes",
                "createIndexes", "dropIndexes", "collStats", "count", "distinct", "drop", "create", "collMod").contains(name)) {
            if (target.collection().isEmpty() || !command.path(name).isTextual()
                    || !command.path(name).asText().equals(target.collection())) {
                throw new IllegalArgumentException("Command collection must exactly match the selected collection");
            }
        }
        if (name.equals("find")) {
            fields(command, Set.of("find", "filter", "projection", "sort", "skip", "limit", "hint", "collation", "comment", "maxTimeMS", "batchSize"));
            return read("mongo.find", safeExpressions(command), "Unrecognized or executable expressions require exact one-time review");
        }
        if (name.equals("aggregate")) {
            fields(command, Set.of("aggregate", "pipeline", "cursor", "allowDiskUse", "hint", "collation", "comment", "maxTimeMS"));
            if (!command.path("pipeline").isArray() || command.path("pipeline").size() > 64) throw new IllegalArgumentException("Pipeline must be an array of at most 64 stages");
            boolean safe = true, writes = false;
            for (JsonNode stage : command.path("pipeline")) {
                if (!stage.isObject() || stage.size() != 1) throw new IllegalArgumentException("Each pipeline stage must have one operator");
                String key = stage.fieldNames().next();
                if (Set.of("$out", "$merge").contains(key)) writes = true;
                if (!READ_STAGES.contains(key)) safe = false;
                else if (!safeExpressions(stage.path(key))) safe = false;
            }
            if(writes)return new Classification("mongo.aggregate_write", Effect.WRITE, false, "Pipeline writes may target another collection/database; validate all namespaces before execution");
            return read("mongo.aggregate", safe, "Joins, nested/unknown pipelines and executable expressions require explicit review and namespace validation");
        }
        if (name.equals("explain")) {
            fields(command, Set.of("explain", "verbosity", "comment", "maxTimeMS"));
            String verbosity = command.path("verbosity").asText("queryPlanner");
            if (!Set.of("queryPlanner", "executionStats", "allPlansExecution").contains(verbosity)) throw new IllegalArgumentException("Unsupported Explain verbosity");
            Classification nested = mongo(target, command.path("explain"));
            if (!Set.of("mongo.find", "mongo.aggregate").contains(nested.category())) throw new IllegalArgumentException("Explain requires a find or aggregation command");
            return read("mongo.explain", verbosity.equals("queryPlanner") && nested.reusableRead(), "Execution statistics execute work; unknown nested operations require exact review");
        }
        if(name.equals("listCollections")){
            fields(command,Set.of("listCollections","filter"));
            if(!command.path(name).isIntegralNumber()||command.path(name).asInt()!=1)throw new IllegalArgumentException("listCollections must be 1");
            return read("mongo.metadata",safeExpressions(command),"Only validated metadata filters are permitted");
        }
        if(name.equals("listIndexes")){fields(command,Set.of("listIndexes"));return read("mongo.metadata",true,"Bounded collection-index metadata");}
        if (MONGO_META.contains(name)) return read("mongo.metadata", false, "Metadata options and server version require verified capability checks");
        if (Set.of("insert", "update", "findAndModify", "create", "createIndexes", "collMod").contains(name)) {
            return new Classification("mongo." + name, Effect.WRITE, false, "Exact operation review required; writes are not reusable reads");
        }
        if (Set.of("delete", "drop", "dropDatabase", "dropIndexes", "renameCollection").contains(name)) {
            return new Classification("mongo." + name, Effect.DESTRUCTIVE, false, "Destructive operation; verify every affected namespace");
        }
        return new Classification("mongo.administration", Effect.ADMINISTRATION, false, "Unknown/admin commands require a verified operation adapter and exact review");
    }

    private static Classification redis(JsonNode command) {
        if (!command.isArray() || command.isEmpty() || command.size() > 1024) throw new IllegalArgumentException("Redis command must be an array of 1..1024 arguments");
        NativeRedisArguments.validate(command);
        String name = NativeRedisArguments.text(command,0).toUpperCase(Locale.ROOT);
        if (!name.matches("[A-Z][A-Z0-9_.]{0,63}")) throw new IllegalArgumentException("Invalid Redis command name");
        if (Set.of("AUTH", "HELLO", "SELECT", "QUIT", "RESET", "READONLY", "READWRITE", "ASKING", "MULTI", "EXEC", "DISCARD", "WATCH", "UNWATCH").contains(name)) {
            throw new IllegalArgumentException("Connection/session commands require the dedicated managed workflow");
        }
        if (REDIS_READ.contains(name)) return read("redis.read", true, "Bounded command adapter and exact key scope still required");
        if (REDIS_WRITE.contains(name)) return new Classification("redis.write", Effect.WRITE, false, "Native mutation; exact key and argument review required");
        if (REDIS_DESTRUCTIVE.contains(name)) return new Classification("redis.destructive", Effect.DESTRUCTIVE, false, "May destroy/consume values or affect the entire database");
        // Server command flags alone cannot establish key scope, reply bounds or module safety.
        return new Classification("redis.administration", Effect.ADMINISTRATION, false, "Scripts, modules and unknown/admin commands require verified adapters and exact review");
    }

    private static Classification read(String category, boolean verified, String reason) {
        // An unverified expression must not inherit a read policy, including broad environment policies.
        return new Classification(category, verified ? Effect.READ : Effect.ADMINISTRATION, verified, reason);
    }

    private static boolean safeExpressions(JsonNode node) {
        if (node.isObject()) {
            var fields = node.fields();
            while (fields.hasNext()) {
                var field = fields.next();
                if (field.getKey().startsWith("$") && !SAFE_MONGO_EXPRESSIONS.contains(field.getKey())) return false;
                if (!safeExpressions(field.getValue())) return false;
            }
        } else if (node.isArray()) for (JsonNode child : node) if (!safeExpressions(child)) return false;
        return true;
    }

    private static void fields(JsonNode value, Set<String> permitted) {
        value.fieldNames().forEachRemaining(key -> { if (!permitted.contains(key)) throw new IllegalArgumentException("Unsupported MongoDB command option: " + key); });
    }

    static void bound(JsonNode input) {
        if (input == null) throw new IllegalArgumentException("Command is required");
        var nodes = new ArrayDeque<Map.Entry<JsonNode, Integer>>();
        nodes.add(Map.entry(input, 0));
        int count = 0;
        long bytes = 0;
        while (!nodes.isEmpty()) {
            var item = nodes.removeLast();
            if (++count > 16_384 || item.getValue() > 32) throw new IllegalArgumentException("Native command exceeds structural limits");
            JsonNode node = item.getKey();
            if (node.isObject()) {
                var fields = node.fields();
                while (fields.hasNext()) {
                    var field = fields.next();
                    if (field.getKey().indexOf('\0') >= 0 || field.getKey().length() > 1024) throw new IllegalArgumentException("Invalid command field name");
                    bytes += field.getKey().getBytes(StandardCharsets.UTF_8).length;
                    nodes.add(Map.entry(field.getValue(), item.getValue() + 1));
                }
            } else if (node.isArray()) {
                for (JsonNode child : node) nodes.add(Map.entry(child, item.getValue() + 1));
            } else {
                String text = node.asText();
                if (text.length() > 131072) throw new IllegalArgumentException("Native value exceeds request allowance");
                bytes += text.getBytes(StandardCharsets.UTF_8).length;
            }
            if (bytes > 131072 || nodes.size() > 16384) throw new IllegalArgumentException("Native command exceeds request allowance");
        }
    }

    private NativeCommand() { }
}

package io.doindev.codegraph.dba;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import java.util.*;

/** Browser tree projection of the same bounded native reads used by workspaces. */
final class NativeMetadataTree {
    static ObjectNode load(NativeConnections.Lease lease,NativeTarget target,JsonNode request,QueryJobs.Job job)throws Exception{
        String kind=request.path("kind").asText("root");
        var result=Profiles.JSON.createObjectNode().put("transport",target.transport().id).put("database",target.database());
        var nodes=result.putArray("nodes");
        if(kind.equals("root")){
            node(nodes,"database",target.database(),true,target);
            result.put("coverage","Configured database only; use a native workspace with an explicit database to inspect another target.");
            return result;
        }
        if(kind.equals("native_database")){
            if(target.transport()==DatabaseTransport.MONGODB){node(nodes,"collections","Collections",true,target);node(nodes,"views","Views",true,target);}
            else node(nodes,"keys","Keys",true,target);
            return result;
        }
        if(kind.equals("native_collection")){node(nodes,"indexes","Indexes",true,target);return result;}
        JsonNode command;
        if(kind.equals("native_collections")||kind.equals("native_views")){
            ObjectNode metadata=Profiles.JSON.createObjectNode().put("listCollections",1);
            metadata.putObject("filter").put("type",kind.equals("native_views")?"view":"collection");command=metadata;
        }else if(kind.equals("native_indexes"))command=Profiles.JSON.createObjectNode().put("listIndexes",target.collection());
        else if(kind.equals("native_keys")){
            command=Profiles.JSON.createArrayNode().add("SCAN").add(request.path("offset").asText("0")).add("MATCH").add(request.path("pattern").asText("*"));
        }else throw new IllegalArgumentException("Unsupported native metadata branch");
        ObjectNode rows=NativeReadExecutor.execute(lease,target,command,new NativeReadExecutor.Limits(100,1<<20,job.remainingSeconds()),()->job.cancelled);
        List<ObjectNode> found=new ArrayList<>();
        for(JsonNode row:rows.path("entries")){
            if(kind.equals("native_keys")){
                ObjectNode key=keyNode(row,target);
                if(key==null)result.put("truncated",true).put("warning","Some key names exceed the interactive byte allowance; refine the scan pattern.");
                else found.add(key);
                continue;
            }
            String name=kind.equals("native_keys")?row.path("text").asText(""):row.path("name").asText("");
            if(name.isBlank()||name.length()>255||row.path("truncated").asBoolean()||row.path("documentOmitted").asBoolean()){
                result.put("truncated",true).put("warning","Some names require the typed native workspace and cannot be represented as text tree items.");continue;
            }
            String child=kind.equals("native_collections")?"collection":kind.equals("native_views")?"view":kind.equals("native_indexes")?"index":"key";
            var entry=Profiles.JSON.createObjectNode();var one=Profiles.JSON.createArrayNode();node(one,child,name,child.equals("collection"),target);entry=(ObjectNode)one.get(0);
            if(child.equals("collection")||child.equals("view"))entry.put("collection",name);
            entry.put("nativeObject",true);entry.set("command",commandFor(child,name,target));
            found.add(entry);
        }
        found.sort(Comparator.comparing(n->n.path("name").asText(),String.CASE_INSENSITIVE_ORDER));found.forEach(nodes::add);
        if(rows.path("truncated").asBoolean())result.put("truncated",true).put("warning","Metadata exceeded the interactive allowance; use a filtered native metadata command to narrow the inventory.");
        if(rows.has("nextCursor")&&!rows.path("scanComplete").asBoolean())result.put("nextOffset",rows.path("nextCursor").asText());
        result.put("coverage","bounded_live_non_snapshot");return result;
    }
    static ObjectNode keyNode(JsonNode row,NativeTarget target){
        if(row.path("truncated").asBoolean()||!row.path("base64").isTextual())return null;
        String encoded=row.path("base64").asText();
        var argument=Profiles.JSON.createObjectNode().put("base64",encoded);
        var command=Profiles.JSON.createArrayNode().add("TYPE").add(argument);
        try{NativeRedisArguments.validate(command);}catch(IllegalArgumentException invalid){return null;}
        String text=row.path("text").asText("");
        String name=!text.isBlank()&&text.length()<=255&&text.chars().noneMatch(Character::isISOControl)
                ?text:encoded.isEmpty()?"[empty key]":"[binary key: "+encoded.substring(0,Math.min(48,encoded.length()))+(encoded.length()>48?"…":"")+"]";
        var one=Profiles.JSON.createArrayNode();node(one,"key",name,false,target);
        ObjectNode entry=(ObjectNode)one.get(0);
        entry.put("key","key:base64:"+encoded).put("keyEncoding","base64").put("nativeObject",true);
        entry.set("command",command);return entry;
    }
    private static JsonNode commandFor(String kind,String name,NativeTarget target){
        return switch(kind){
            case "key" -> Profiles.JSON.createArrayNode().add("TYPE").add(name);
            case "index" -> Profiles.JSON.createObjectNode().put("listIndexes",target.collection());
            default -> Profiles.JSON.createObjectNode().put("find",name).put("limit",100).set("filter",Profiles.JSON.createObjectNode());
        };
    }
    private static void node(ArrayNode list,String kind,String name,boolean branch,NativeTarget target){
        list.addObject().put("key",kind+":"+name).put("kind","native_"+kind).put("name",name).put("branch",branch)
                .put("database",target.database()).put("collection",target.collection()).put("transport",target.transport().id);
    }
    private NativeMetadataTree(){}
}

package io.doindev.codegraph.dba;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import io.lettuce.core.codec.ByteArrayCodec;
import org.bson.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Reviewed, single-target CRUD. No scripts, server administration, implicit retries or w:0. */
final class NativeMutations {
    static void validate(NativeTarget target,JsonNode command){
        NativeCommand.classify(target,command);
        if(target.transport()==DatabaseTransport.MONGODB){
            String name=command.fieldNames().next();
            switch(name){
                case "insert" -> {
                    fields(command,Set.of("insert","documents","ordered"));
                    array(command.path("documents"),"documents");
                    for(JsonNode item:command.path("documents"))if(!item.isObject()||item.isEmpty())throw new IllegalArgumentException("Insert documents must be nonempty objects");
                }
                case "update" -> {
                    fields(command,Set.of("update","updates","ordered"));array(command.path("updates"),"updates");
                    for(JsonNode item:command.path("updates")){
                        fields(item,Set.of("q","u","multi","upsert","arrayFilters","collation"));
                        if(!item.path("q").isObject()||item.path("q").isEmpty())throw new IllegalArgumentException("Single-document updates require a nonempty filter");
                        if(!item.path("u").isObject()&&!item.path("u").isArray())throw new IllegalArgumentException("Update must be a document or pipeline");
                        if(item.has("multi")&&(!item.path("multi").isBoolean()||item.path("multi").asBoolean()))throw new IllegalArgumentException("Multi-document writes require a dedicated bounded bulk workflow");
                        if(item.has("upsert")&&!item.path("upsert").isBoolean())throw new IllegalArgumentException("upsert must be boolean");
                    }
                }
                case "delete" -> {
                    fields(command,Set.of("delete","deletes","ordered"));array(command.path("deletes"),"deletes");
                    for(JsonNode item:command.path("deletes")){
                        fields(item,Set.of("q","limit","collation"));
                        if(!item.path("q").isObject()||item.path("q").isEmpty()||!item.path("limit").isIntegralNumber()||item.path("limit").asInt()!=1)
                            throw new IllegalArgumentException("Deletion requires a nonempty filter and limit: 1; unbounded deletion is not enabled");
                    }
                }
                case "create" -> {
                    fields(command,Set.of("create","validator","validationLevel","validationAction","collation","capped","size","max","timeseries","expireAfterSeconds","viewOn","pipeline"));
                    if(command.has("viewOn")||command.has("pipeline")){
                        fields(command,Set.of("create","viewOn","pipeline","collation"));
                        view(target,command);
                    }
                }
                case "collMod" -> {
                    fields(command,Set.of("collMod","validator","validationLevel","validationAction","viewOn","pipeline"));
                    if(command.has("viewOn")||command.has("pipeline")){
                        fields(command,Set.of("collMod","viewOn","pipeline"));
                        view(target,command);
                    }else if(command.size()==1)throw new IllegalArgumentException("Supply an explicit validator or validation setting");
                }
                case "createIndexes" -> {fields(command,Set.of("createIndexes","indexes"));array(command.path("indexes"),"indexes");}
                case "drop" -> fields(command,Set.of("drop"));
                case "dropIndexes" -> {fields(command,Set.of("dropIndexes","index"));if(!command.path("index").isTextual()||command.path("index").asText().isBlank())throw new IllegalArgumentException("An exact index name or explicitly reviewed * is required");}
                default -> throw new IllegalArgumentException("No verified native mutation adapter for this MongoDB command");
            }
            if(command.has("ordered")&&!command.path("ordered").isBoolean())throw new IllegalArgumentException("ordered must be boolean");
        }else{
            String name=command.get(0).asText().toUpperCase(Locale.ROOT);int size=command.size();
            switch(name){
                case "SET" -> {arity(size,3,6);setOptions(command);}
                case "RENAME","RENAMENX" -> arity(size,3,3);
                case "EXPIRE","PEXPIRE" -> {arity(size,3,3);integer(command.get(2).asText());}
                case "PERSIST" -> arity(size,2,2);
                case "HSET" -> {arity(size,4,202);if(size%2!=0)throw new IllegalArgumentException("HSET requires field/value pairs");}
                case "LPUSH","RPUSH","SADD","HDEL","SREM","ZREM" -> arity(size,3,102);
                case "DEL","UNLINK" -> arity(size,2,101);
                case "ZADD" -> {arity(size,4,202);if(size%2!=0)throw new IllegalArgumentException("ZADD requires score/member pairs");for(int i=2;i<size;i+=2)if(!Double.isFinite(Double.parseDouble(command.get(i).asText())))throw new IllegalArgumentException("Finite sorted-set scores required");}
                default -> throw new IllegalArgumentException("No verified native mutation adapter for this Redis command");
            }
        }
    }
    static JsonNode execute(NativeConnections.Lease lease,NativeTarget target,JsonNode command,QueryJobs.Job job)throws Exception {
        validate(target,command);job.outcome="not_started";
        try{
            if(job.cancelled)throw new java.util.concurrent.CancellationException();
            if(target.transport()==DatabaseTransport.MONGODB){
                BsonDocument request=BsonDocument.parse(command.toString());
                request.put("maxTimeMS",new BsonInt64(job.remainingSeconds()*1000L));
                job.outcome="partial_or_unknown";
                RawBsonDocument reply=lease.mongo.getDatabase(target.database()).runCommand(request,RawBsonDocument.class);
                var bounded=new NativeResults("mutation",1,job.byteLimit);NativeReadExecutor.addDocument(bounded,reply);
                boolean errors=reply.containsKey("writeErrors")||reply.containsKey("writeConcernError");
                ObjectNode result=bounded.finish().put("outcome",errors?"partial_or_unknown":"acknowledged");
                if(errors){job.result=result;throw new IllegalArgumentException("MongoDB reported write or write-concern errors; inspect the bounded reply and reconcile before retry");}
                job.outcome="acknowledged";return result;
            }
            try(var connection=lease.redis.connect(ByteArrayCodec.INSTANCE)){
                connection.setTimeout(java.time.Duration.ofSeconds(job.remainingSeconds()));
                var redis=connection.sync();redis.select(Integer.parseInt(target.database()));if(job.cancelled)throw new java.util.concurrent.CancellationException();
                String name=command.get(0).asText().toUpperCase(Locale.ROOT);byte[] key=bytes(command,1);Object value;
                job.outcome="partial_or_unknown";
                switch(name){
                    case "SET" -> value=redis.set(key,bytes(command,2),setOptions(command));
                    case "DEL" -> value=redis.del(tail(command,1));
                    case "UNLINK" -> value=redis.unlink(tail(command,1));
                    case "RENAME" -> value=redis.rename(key,bytes(command,2));
                    case "RENAMENX" -> value=redis.renamenx(key,bytes(command,2));
                    case "EXPIRE" -> value=redis.expire(key,integer(command.get(2).asText()));
                    case "PEXPIRE" -> value=redis.pexpire(key,integer(command.get(2).asText()));
                    case "PERSIST" -> value=redis.persist(key);
                    case "HSET" -> {Map<byte[],byte[]> fields=new LinkedHashMap<>();for(int i=2;i<command.size();i+=2)fields.put(bytes(command,i),bytes(command,i+1));value=redis.hset(key,fields);}
                    case "HDEL" -> value=redis.hdel(key,tail(command,2));
                    case "LPUSH" -> value=redis.lpush(key,tail(command,2));
                    case "RPUSH" -> value=redis.rpush(key,tail(command,2));
                    case "SADD" -> value=redis.sadd(key,tail(command,2));
                    case "SREM" -> value=redis.srem(key,tail(command,2));
                    case "ZREM" -> value=redis.zrem(key,tail(command,2));
                    case "ZADD" -> {List<io.lettuce.core.ScoredValue<byte[]>> members=new ArrayList<>();for(int i=2;i<command.size();i+=2)members.add(io.lettuce.core.ScoredValue.just(Double.parseDouble(command.get(i).asText()),bytes(command,i+1)));value=redis.zadd(key,members.toArray(io.lettuce.core.ScoredValue[]::new));}
                    default -> throw new IllegalArgumentException("Unsupported native mutation");
                }
                job.outcome="acknowledged";ObjectNode result=Profiles.JSON.createObjectNode().put("kind","mutation").put("outcome",job.outcome);
                result.set("value",Profiles.JSON.valueToTree(value));if(name.equals("SET"))result.put("applied",value!=null);return result;
            }
        }finally{ /* Any transport loss/cancellation after submission remains partial_or_unknown. */ }
    }
    private static void fields(JsonNode value,Set<String> allowed){if(!value.isObject())throw new IllegalArgumentException("Native operation entry must be an object");value.fieldNames().forEachRemaining(key->{if(!allowed.contains(key))throw new IllegalArgumentException("Unsupported native operation field: "+key);});}
    private static void view(NativeTarget target,JsonNode command){
        String source=NativeTarget.text(command,"viewOn",255);
        if(source.startsWith("system.")||source.contains("$"))throw new IllegalArgumentException("System collections cannot be view sources");
        if(!command.path("pipeline").isArray())throw new IllegalArgumentException("Supply viewOn and an explicit pipeline array together");
        var query=Profiles.JSON.createObjectNode().put("aggregate",source);query.set("pipeline",command.path("pipeline"));
        var sourceTarget=new NativeTarget(target.transport(),target.connectionId(),target.connectionName(),target.database(),source,target.topology());
        if(!NativeCommand.classify(sourceTarget,query).reusableRead())throw new IllegalArgumentException("Views require a verified, read-only same-database pipeline; executable expressions, output stages and cross-namespace joins are not enabled");
    }
    private static void array(JsonNode value,String name){if(!value.isArray()||value.isEmpty()||value.size()>100)throw new IllegalArgumentException(name+" must contain 1..100 entries");}
    private static void arity(int count,int min,int max){if(count<min||count>max)throw new IllegalArgumentException("Unexpected native command argument count");}
    private static long integer(String value){if(!value.matches("-?[0-9]{1,18}"))throw new IllegalArgumentException("Bounded integer argument required");return Long.parseLong(value);}
    private static io.lettuce.core.SetArgs setOptions(JsonNode command){
        var args=new io.lettuce.core.SetArgs();boolean condition=false,expiry=false;
        for(int i=3;i<command.size();i++){
            String option=command.get(i).asText().toUpperCase(Locale.ROOT);
            switch(option){
                case "NX","XX" -> {
                    if(condition)throw new IllegalArgumentException("SET accepts only one of NX or XX");
                    condition=true;if(option.equals("NX"))args.nx();else args.xx();
                }
                case "KEEPTTL","EX","PX" -> {
                    if(expiry)throw new IllegalArgumentException("SET accepts only one expiry option");
                    expiry=true;
                    if(option.equals("KEEPTTL"))args.keepttl();
                    else{
                        if(++i>=command.size())throw new IllegalArgumentException("SET expiry requires a positive duration");
                        long duration=integer(command.get(i).asText());
                        if(duration<=0)throw new IllegalArgumentException("SET expiry requires a positive duration");
                        if(option.equals("EX"))args.ex(duration);else args.px(duration);
                    }
                }
                default -> throw new IllegalArgumentException("Supported SET options: NX or XX, plus EX/PX duration or KEEPTTL. GET and unknown options require another bounded adapter.");
            }
        }
        return args;
    }
    private static byte[] bytes(JsonNode command,int i){return NativeRedisArguments.bytes(command,i);}
    private static byte[][] tail(JsonNode command,int start){byte[][] values=new byte[command.size()-start][];for(int i=start;i<command.size();i++)values[i-start]=bytes(command,i);return values;}
    private NativeMutations(){}
}

package io.doindev.codegraph.dba;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.mongodb.client.*;
import io.lettuce.core.*;
import io.lettuce.core.codec.ByteArrayCodec;
import org.bson.*;
import org.bson.json.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.CancellationException;
import java.util.concurrent.TimeUnit;
import java.util.function.BooleanSupplier;

/** Small verified read adapters. Callers must authorize before acquiring a lease. */
final class NativeReadExecutor {
    // MongoDB also caps a server cursor batch at 16 MiB. Keep its documents raw,
    // limit their count, and expand only size-checked documents into retained JSON.
    static final int MONGO_BATCH_DOCUMENTS=16;
    record Limits(int rows,int bytes,int timeoutSeconds) {
        Limits { if(rows<1||rows>10000||bytes<16384||bytes>4<<20||timeoutSeconds<1||timeoutSeconds>300)throw new IllegalArgumentException("Invalid native execution limits"); }
    }
    private static final JsonWriterSettings EXTENDED=JsonWriterSettings.builder().outputMode(JsonMode.EXTENDED).build();

    static ObjectNode execute(NativeConnections.Lease lease,NativeTarget target,JsonNode command,Limits limits,BooleanSupplier cancelled)throws Exception {
        check(cancelled);
        NativeCommand.Classification classification=NativeCommand.classify(target,command);
        if(!classification.reusableRead())throw new IllegalArgumentException("This command has no verified native read adapter; request the appropriate reviewed operation");
        ObjectNode result=target.transport()==DatabaseTransport.MONGODB?mongo(lease.mongo,target,command,limits,cancelled):redis(lease.redis,target,command,limits,cancelled);
        result.set("target",target.json());result.set("classification",classification.json());
        result.put("consistency","live_non_snapshot").put("hardMemoryLimit",false);
        return result;
    }

    private static ObjectNode mongo(MongoClient client,NativeTarget target,JsonNode command,Limits limits,BooleanSupplier cancelled)throws Exception {
        var database=client.getDatabase(target.database());String operation=command.fieldNames().next();
        if(operation.equals("listCollections")){
            var query=database.listCollections(RawBsonDocument.class).batchSize(batch(limits)).maxTime(limits.timeoutSeconds(),TimeUnit.SECONDS);
            if(command.has("filter"))query.filter(document(command.path("filter")));
            try(var cursor=query.iterator()){return documents(cursor,limits,cancelled);}
        }
        var collection=database.getCollection(target.collection(),RawBsonDocument.class);
        if(operation.equals("listIndexes")){
            try(var cursor=collection.listIndexes(RawBsonDocument.class).batchSize(batch(limits)).maxTime(limits.timeoutSeconds(),TimeUnit.SECONDS).iterator()){
                return documents(cursor,limits,cancelled);
            }
        }
        if(operation.equals("find")) {
            var query=collection.find(document(command.path("filter")));
            if(command.has("projection"))query.projection(document(command.path("projection")));
            if(command.has("sort"))query.sort(document(command.path("sort")));
            if(command.has("skip"))query.skip(number(command,"skip",0,1000000));
            int requested=command.has("limit")?number(command,"limit",1,1000000):limits.rows()+1;
            query.limit(Math.min(requested,limits.rows()+1)).batchSize(batch(limits)).maxTime(limits.timeoutSeconds(),TimeUnit.SECONDS);
            // Hints/collations need typed, validated translation before they can be advertised.
            rejectOptions(command,Set.of("find","filter","projection","sort","skip","limit"));
            try(var cursor=query.iterator()) { return documents(cursor,limits,cancelled); }
        }
        if(operation.equals("aggregate")) {
            rejectOptions(command,Set.of("aggregate","pipeline","allowDiskUse"));
            if(command.has("allowDiskUse")&&!command.path("allowDiskUse").isBoolean())throw new IllegalArgumentException("allowDiskUse must be a boolean");
            List<BsonDocument> pipeline=new ArrayList<>();for(JsonNode stage:command.path("pipeline"))pipeline.add(document(stage));
            pipeline.add(new BsonDocument("$limit",new BsonInt32(limits.rows()+1)));
            try(var cursor=collection.aggregate(pipeline).allowDiskUse(command.path("allowDiskUse").asBoolean(false))
                    .batchSize(batch(limits)).maxTime(limits.timeoutSeconds(),TimeUnit.SECONDS).iterator()) {
                return documents(cursor,limits,cancelled);
            }
        }
        if(operation.equals("explain")) {
            rejectOptions(command,Set.of("explain","verbosity"));
            BsonDocument explain=document(command);explain.put("maxTimeMS",new BsonInt64(limits.timeoutSeconds()*1000L));
            RawBsonDocument plan=database.runCommand(explain,RawBsonDocument.class);
            var result=new NativeResults("plan",1,limits.bytes());addDocument(result,plan);
            return result.finish().put("estimated",true);
        }
        throw new IllegalArgumentException("Native MongoDB read operation is not implemented");
    }

    private static ObjectNode documents(MongoCursor<RawBsonDocument> cursor,Limits limits,BooleanSupplier cancelled)throws Exception {
        var result=new NativeResults("documents",limits.rows(),limits.bytes());
        while(true) {
            check(cancelled);if(!cursor.hasNext())break;check(cancelled);
            RawBsonDocument value=cursor.next();
            if(!addDocument(result,value))break;
        }
        return result.finish().put("encoding","bson_extended_json");
    }
    static boolean addDocument(NativeResults result,RawBsonDocument document)throws Exception {
        int bytes=document.getByteBuffer().remaining();
        // Keep the driver document raw until its size is known. Expanding a 16 MiB BSON
        // document into millions of Java/Jackson objects defeats bounded result admission.
        if(bytes>256*1024){
            result.incomplete("large_document_omitted");
            return result.add(Profiles.JSON.createObjectNode().put("documentOmitted",true).put("encodedBytes",bytes)
                    .put("guidance","Use a narrower projection; documents above 256 KiB are not expanded into the interactive result model."));
        }
        return result.add(Profiles.JSON.readTree(document.toJson(EXTENDED)));
    }

    private static ObjectNode redis(RedisClient client,NativeTarget target,JsonNode command,Limits limits,BooleanSupplier cancelled) {
        try(var connection=client.connect(ByteArrayCodec.INSTANCE)) {
            connection.setTimeout(java.time.Duration.ofSeconds(limits.timeoutSeconds()));
            var commands=connection.sync();commands.select(Integer.parseInt(target.database()));
            String operation=command.get(0).asText().toUpperCase(Locale.ROOT);
            var result=new NativeResults("values",limits.rows(),limits.bytes());
            switch(operation) {
                case "GET" -> {
                    arity(command,2);byte[] key=key(command,1);
                    String type=commands.type(key);
                    if(type.equals("none"))result.add(Profiles.JSON.createObjectNode().put("missing",true));
                    else {
                        if(!type.equals("string"))throw new IllegalArgumentException("Selected key is not a string; use its type-specific viewer");
                        byte[] preview=commands.getrange(key,0,8192);check(cancelled);
                        ObjectNode entry=NativeResults.binary(preview,8192);entry.put("previewOnly",true);
                        result.add(entry);
                    }
                }
                case "TYPE" -> { arity(command,2);result.add(Profiles.JSON.getNodeFactory().textNode(commands.type(key(command,1)))); }
                case "TTL" -> { arity(command,2);result.add(Profiles.JSON.getNodeFactory().numberNode(commands.ttl(key(command,1)))); }
                case "PTTL" -> { arity(command,2);result.add(Profiles.JSON.getNodeFactory().numberNode(commands.pttl(key(command,1)))); }
                case "STRLEN" -> { arity(command,2);result.add(Profiles.JSON.getNodeFactory().numberNode(commands.strlen(key(command,1)))); }
                case "DBSIZE" -> { arity(command,1);result.add(Profiles.JSON.getNodeFactory().numberNode(commands.dbsize())); }
                case "PING" -> { arity(command,1);result.add(Profiles.JSON.getNodeFactory().textNode(commands.ping())); }
                case "SCAN" -> {
                    if(command.size()!=2&&command.size()!=4)throw new IllegalArgumentException("Bounded SCAN accepts cursor and optional MATCH pattern; COUNT is application-managed");
                    String cursor=command.get(1).asText();if(!cursor.matches("[0-9]{1,20}"))throw new IllegalArgumentException("Invalid Redis scan cursor");
                    ScanArgs args=ScanArgs.Builder.limit(Math.min(64,limits.rows()));
                    if(command.size()==4) { if(!command.get(2).asText().equalsIgnoreCase("MATCH"))throw new IllegalArgumentException("Expected MATCH pattern");args.match(command.get(3).asText()); }
                    KeyScanCursor<byte[]> page=commands.scan(ScanCursor.of(cursor),args);
                    for(byte[] key:page.getKeys()){check(cancelled);if(!result.add(NativeResults.binary(key,8192)))break;}
                    ObjectNode out=result.finish();out.put("scanComplete",page.isFinished()&&!out.path("truncated").asBoolean());
                    if(!out.path("truncated").asBoolean())out.put("nextCursor",page.getCursor());
                    else out.put("requiresRefinement",true).put("warning","Scan page exceeded allowance; refine the pattern. No continuation is returned because entries would be skipped.");
                    return out;
                }
                default -> {return NativeRedisReads.execute(commands,command,limits,cancelled);}
            }
            check(cancelled);return result.finish();
        }
    }

    private static BsonDocument document(JsonNode value) {
        if(value.isMissingNode())return new BsonDocument();
        if(!value.isObject())throw new IllegalArgumentException("MongoDB filter/projection/stage must be an object");
        try{return BsonDocument.parse(value.toString());}catch(RuntimeException invalid){throw new IllegalArgumentException("Malformed BSON Extended JSON value");}
    }
    private static int number(JsonNode input,String field,int min,int max) {
        JsonNode value=input.path(field);if(!value.isIntegralNumber()||!value.canConvertToInt()||value.intValue()<min||value.intValue()>max)throw new IllegalArgumentException("Invalid "+field);return value.intValue();
    }
    private static int batch(Limits limits){return Math.min(MONGO_BATCH_DOCUMENTS,limits.rows()+1);}
    private static byte[] key(JsonNode command,int index) { byte[] value=NativeRedisArguments.bytes(command,index);if(value.length>8192)throw new IllegalArgumentException("Key exceeds interactive key allowance");return value; }
    private static void arity(JsonNode command,int count) { if(command.size()!=count)throw new IllegalArgumentException("Unexpected Redis arguments"); }
    private static void rejectOptions(JsonNode command,Set<String> allowed) { command.fieldNames().forEachRemaining(name->{if(!allowed.contains(name))throw new IllegalArgumentException("Option requires a verified adapter: "+name);}); }
    private static void check(BooleanSupplier cancelled) { if(cancelled.getAsBoolean()||Thread.currentThread().isInterrupted())throw new CancellationException(); }
    private NativeReadExecutor() { }
}

package io.doindev.codegraph.dba;

import com.fasterxml.jackson.databind.JsonNode;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Binary keys/values are explicit; command names and control syntax are always text. */
final class NativeRedisArguments {
    private static final Set<String> KEY_COMMANDS=Set.of(
            "GET","GETRANGE","STRLEN","TYPE","EXISTS","TTL","PTTL","EXPIRETIME","PEXPIRETIME",
            "HGET","HLEN","HEXISTS","HSCAN","LRANGE","LINDEX","LLEN","SSCAN","SCARD","SISMEMBER",
            "ZRANGE","ZREVRANGE","ZCARD","ZSCORE","ZSCAN","XRANGE","XREVRANGE","XLEN","GETBIT",
            "SET","DEL","UNLINK","RENAME","RENAMENX","EXPIRE","PEXPIRE","PERSIST","HSET","HDEL",
            "LPUSH","RPUSH","SADD","SREM","ZADD","ZREM");

    static void validate(JsonNode command){
        String name=text(command,0).toUpperCase(Locale.ROOT);
        for(int i=1;i<command.size();i++){
            JsonNode value=command.get(i);
            if(!value.isTextual()){
                if(!binaryPosition(name,i))throw new IllegalArgumentException("Binary values are allowed only in supported key/value positions; commands, options, numbers, cursors and patterns must be text");
                byte[] decoded=bytes(command,i);
                if(keyOrField(name,i)&&decoded.length>8192)throw new IllegalArgumentException("Key/field exceeds 8192-byte interactive allowance");
            }else if(keyOrField(name,i)&&value.asText().getBytes(StandardCharsets.UTF_8).length>8192){
                throw new IllegalArgumentException("Key/field exceeds 8192-byte interactive allowance");
            }
        }
    }
    static String text(JsonNode command,int index){
        JsonNode value=command.get(index);
        if(value==null||!value.isTextual())throw new IllegalArgumentException("Redis control arguments must be text");
        return value.asText();
    }
    static byte[] bytes(JsonNode command,int index){
        JsonNode value=command.get(index);
        if(value==null)throw new IllegalArgumentException("Missing Redis argument");
        if(value.isTextual())return value.asText().getBytes(StandardCharsets.UTF_8);
        if(!value.isObject()||value.size()!=1||!value.path("base64").isTextual())
            throw new IllegalArgumentException("Redis values must be text or an object containing only base64");
        String encoded=value.path("base64").asText();
        if(encoded.length()>87384)throw new IllegalArgumentException("Binary values exceed the 64 KiB per-value input allowance");
        try{
            byte[] decoded=Base64.getDecoder().decode(encoded);
            if(decoded.length>65536||!Base64.getEncoder().encodeToString(decoded).equals(encoded))
                throw new IllegalArgumentException();
            return decoded;
        }catch(IllegalArgumentException invalid){
            throw new IllegalArgumentException("Binary arguments require canonical padded base64, at most 64 KiB decoded");
        }
    }
    private static boolean binaryPosition(String name,int index){
        if(keyOrField(name,index))return true;
        return switch(name){
            case "SET" -> index==2;
            case "HSET" -> index>=2;
            case "LPUSH","RPUSH","SADD","SREM","ZREM" -> index>=2;
            case "ZADD" -> index>=3&&index%2==1;
            case "HGET","HEXISTS","SISMEMBER","ZSCORE" -> index==2;
            default -> false;
        };
    }
    private static boolean keyOrField(String name,int index){
        if(index==1&&KEY_COMMANDS.contains(name))return true;
        return switch(name){
            case "DEL","UNLINK" -> index>=1;
            case "RENAME","RENAMENX","HGET","HEXISTS" -> index==2;
            case "HSET" -> index>=2&&index%2==0;
            case "HDEL" -> index>=2;
            default -> false;
        };
    }
    private NativeRedisArguments(){}
}

package io.doindev.codegraph.dba;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import io.lettuce.core.*;
import io.lettuce.core.api.sync.RedisCommands;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.CancellationException;
import java.util.function.BooleanSupplier;

/** Type-specific reads. Bounded ranges/cursors plus the transport's wire budget. */
final class NativeRedisReads {
    static ObjectNode execute(RedisCommands<byte[],byte[]> redis,JsonNode command,
            NativeReadExecutor.Limits limits,BooleanSupplier cancelled){
        String name=command.get(0).asText().toUpperCase(Locale.ROOT);
        var out=new NativeResults("values",limits.rows(),limits.bytes());
        byte[] key=command.size()>1?bytes(command,1):null;
        switch(name){
            case "EXISTS" -> {arity(command,2);scalar(out,redis.exists(key));}
            case "EXPIRETIME" -> {arity(command,2);scalar(out,redis.expiretime(key));}
            case "PEXPIRETIME" -> {arity(command,2);scalar(out,redis.pexpiretime(key));}
            case "HLEN" -> {arity(command,2);scalar(out,redis.hlen(key));}
            case "LLEN" -> {arity(command,2);scalar(out,redis.llen(key));}
            case "SCARD" -> {arity(command,2);scalar(out,redis.scard(key));}
            case "ZCARD" -> {arity(command,2);scalar(out,redis.zcard(key));}
            case "XLEN" -> {arity(command,2);scalar(out,redis.xlen(key));}
            case "HEXISTS" -> {arity(command,3);scalar(out,redis.hexists(key,bytes(command,2)));}
            case "SISMEMBER" -> {arity(command,3);scalar(out,redis.sismember(key,bytes(command,2)));}
            case "ZSCORE" -> {arity(command,3);scalar(out,redis.zscore(key,bytes(command,2)));}
            case "GETBIT" -> {arity(command,3);scalar(out,redis.getbit(key,index(command,2)));}
            case "GETRANGE" -> {
                arity(command,4);long start=index(command,2),end=index(command,3);
                if(start<0||end<start||end-start>8191)throw new IllegalArgumentException("GETRANGE requires an ordered, nonnegative range of at most 8192 bytes");
                out.add(NativeResults.binary(redis.getrange(key,start,end),8192));
            }
            case "HGET" -> {arity(command,3);out.add(NativeResults.binary(redis.hget(key,bytes(command,2)),8192));}
            case "LINDEX" -> {arity(command,3);out.add(NativeResults.binary(redis.lindex(key,index(command,2)),8192));}
            case "LRANGE","ZRANGE","ZREVRANGE" -> {
                arity(command,4);long start=index(command,2),end=index(command,3);
                if(start<0||end<start||end-start>=limits.rows())throw new IllegalArgumentException("Use a nonnegative range with at most "+limits.rows()+" entries");
                if(name.equals("LRANGE")){
                    for(byte[] value:redis.lrange(key,start,end)){check(cancelled);if(!out.add(NativeResults.binary(value,8192)))break;}
                }else{
                    var values=name.equals("ZRANGE")?redis.zrangeWithScores(key,start,end):redis.zrevrangeWithScores(key,start,end);
                    for(var value:values){check(cancelled);if(!out.add(scored(value)))break;}
                }
            }
            case "HSCAN","SSCAN","ZSCAN" -> {
                if(command.size()!=3&&command.size()!=5)throw new IllegalArgumentException(name+" accepts key, cursor and optional MATCH pattern; COUNT is application-managed");
                String cursor=command.get(2).asText();if(!cursor.matches("[0-9]{1,20}"))throw new IllegalArgumentException("Invalid cursor");
                ScanArgs args=ScanArgs.Builder.limit(Math.min(64,limits.rows()));
                if(command.size()==5){if(!command.get(3).asText().equalsIgnoreCase("MATCH"))throw new IllegalArgumentException("Expected MATCH");args.match(command.get(4).asText());}
                ScanCursor page;
                if(name.equals("HSCAN")){
                    var found=redis.hscan(key,ScanCursor.of(cursor),args);page=found;
                    for(var entry:found.getMap().entrySet()){
                        check(cancelled);var value=Profiles.JSON.createObjectNode();
                        value.set("field",NativeResults.binary(entry.getKey(),8192));value.set("value",NativeResults.binary(entry.getValue(),8192));
                        if(!out.add(value))break;
                    }
                }else if(name.equals("SSCAN")){
                    var found=redis.sscan(key,ScanCursor.of(cursor),args);page=found;
                    for(byte[] value:found.getValues()){check(cancelled);if(!out.add(NativeResults.binary(value,8192)))break;}
                }else{
                    var found=redis.zscan(key,ScanCursor.of(cursor),args);page=found;
                    for(var value:found.getValues()){check(cancelled);if(!out.add(scored(value)))break;}
                }
                ObjectNode result=out.finish();result.put("scanComplete",page.isFinished()&&!result.path("truncated").asBoolean());
                if(!result.path("truncated").asBoolean())result.put("nextCursor",page.getCursor());
                else result.put("requiresRefinement",true).put("warning","Page exceeded allowance; refine MATCH. No cursor is returned because entries would be skipped.");
                return result;
            }
            case "XRANGE","XREVRANGE" -> {
                arity(command,4);String start=command.get(2).asText(),end=command.get(3).asText();
                for(String boundary:List.of(start,end))if(!boundary.matches("[-+]|\\(?[0-9]{1,20}(?:-[0-9]{1,20})?"))throw new IllegalArgumentException("Use explicit stream IDs, - or +");
                // Lettuce Range always uses lower/upper order, even for Redis' reversed syntax.
                var range=name.equals("XRANGE")?Range.create(start,end):Range.create(end,start);
                var values=name.equals("XRANGE")?redis.xrange(key,range,Limit.from(limits.rows()+1)):redis.xrevrange(key,range,Limit.from(limits.rows()+1));
                for(var message:values){
                    check(cancelled);var entry=Profiles.JSON.createObjectNode().put("id",message.getId());var fields=entry.putArray("fields");
                    int count=0,bytes=0;
                    for(var field:message.getBody().entrySet()){
                        if(++count>100||bytes>16384){entry.put("fieldsTruncated",true);break;}
                        var value=fields.addObject();value.set("field",NativeResults.binary(field.getKey(),8192));value.set("value",NativeResults.binary(field.getValue(),8192));
                        bytes+=Math.min(field.getKey().length,8192)+Math.min(field.getValue().length,8192);
                    }
                    if(!out.add(entry))break;
                }
            }
            default -> throw new IllegalArgumentException("This Redis command needs a bounded reply adapter. Use HSCAN/SSCAN/ZSCAN or bounded LRANGE/XRANGE, not whole-container reads.");
        }
        check(cancelled);return out.finish();
    }
    private static ObjectNode scored(ScoredValue<byte[]> value){var out=Profiles.JSON.createObjectNode().put("score",Double.toString(value.getScore()));out.set("value",NativeResults.binary(value.getValue(),8192));return out;}
    private static void scalar(NativeResults result,Object value){result.add(Profiles.JSON.valueToTree(value));}
    private static byte[] bytes(JsonNode command,int i){byte[] out=NativeRedisArguments.bytes(command,i);if(out.length>8192)throw new IllegalArgumentException("Key/field exceeds 8192-byte interactive allowance");return out;}
    private static long index(JsonNode command,int i){String value=command.get(i).asText();if(!value.matches("-?[0-9]{1,15}"))throw new IllegalArgumentException("Bounded integer index required");return Long.parseLong(value);}
    private static void arity(JsonNode command,int count){if(command.size()!=count)throw new IllegalArgumentException("Unexpected Redis argument count");}
    private static void check(BooleanSupplier cancelled){if(cancelled.getAsBoolean()||Thread.currentThread().isInterrupted())throw new CancellationException();}
    private NativeRedisReads(){}
}
